\begin{tabular}{@{}llcc@{}}
\toprule
Condition & Seed & Bal.\ Acc.\ (\%) & Int.\ Recall (\%) \\
\midrule
Fixed split & 42 & 57.06 & 76.67 \\
 & 123 & 58.07 & 66.67 \\
 & 456 & 57.02 & 78.05 \\
 & 789 & 52.70 & 74.29 \\
\cmidrule{2-4}
 & Mean$\pm$std & $56.2 \pm 2.4$ & $73.9 \pm 5.2$ \\
\midrule
Cross-split & 42 & 57.06 & --- \\
